CREATE TABLE deployments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chain_id bigint NOT NULL, manifest_version text NOT NULL, contract_name text NOT NULL, address text NOT NULL CHECK (address ~ '^0x[0-9a-fA-F]{40}$'), code_hash text NOT NULL CHECK (code_hash ~ '^0x[0-9a-fA-F]{64}$'), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(chain_id, manifest_version, contract_name), UNIQUE(chain_id, address));
CREATE TABLE capabilities (chain_id bigint NOT NULL, manifest_version text NOT NULL, feature text NOT NULL, status text NOT NULL CHECK(status IN ('SUPPORTED','PENDING_CONTRACT','UNSUPPORTED')), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(chain_id, manifest_version, feature));
CREATE TABLE vaults (chain_id bigint NOT NULL, address text NOT NULL CHECK (address ~ '^0x[0-9a-fA-F]{40}$'), strategy text NOT NULL CHECK(strategy IN ('NormalLP','BuyDip','SellPump')), shape_id integer NOT NULL CHECK(shape_id >= 0), owner_role text NOT NULL, as_of_block numeric(78,0) NOT NULL CHECK(as_of_block >= 0), config jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(chain_id,address));
CREATE TABLE config_versions (id bigserial PRIMARY KEY, scope text NOT NULL, version text NOT NULL, value jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope,version));
CREATE TABLE headers (chain_id bigint NOT NULL, block_number numeric(78,0) NOT NULL CHECK(block_number >= 0), block_hash text NOT NULL, parent_hash text NOT NULL, canonical boolean NOT NULL DEFAULT true, finality text NOT NULL CHECK(finality IN ('OBSERVED','CONFIRMED','FINALIZED')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(chain_id,block_hash));
CREATE INDEX headers_chain_number_idx ON headers(chain_id,block_number);
CREATE TABLE raw_logs (chain_id bigint NOT NULL, transaction_hash text NOT NULL, log_index integer NOT NULL CHECK(log_index >= 0), block_hash text NOT NULL, block_number numeric(78,0) NOT NULL CHECK(block_number >= 0), address text NOT NULL, topics jsonb NOT NULL, data text NOT NULL, canonical boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(chain_id,transaction_hash,log_index,block_hash));
CREATE INDEX raw_logs_chain_block_idx ON raw_logs(chain_id,block_number);
CREATE TABLE cursors (chain_id bigint NOT NULL, consumer text NOT NULL, block_number numeric(78,0) NOT NULL CHECK(block_number >= 0), block_hash text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(chain_id,consumer));
CREATE TABLE balances (chain_id bigint NOT NULL, vault_address text NOT NULL, wallet_address text NOT NULL, shares numeric(78,0) NOT NULL CHECK(shares >= 0), as_of_block numeric(78,0) NOT NULL CHECK(as_of_block >= 0), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(chain_id,vault_address,wallet_address));
CREATE TABLE transactions (chain_id bigint NOT NULL, transaction_hash text NOT NULL, wallet_address text, status text NOT NULL, block_number numeric(78,0), metadata jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(chain_id,transaction_hash));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_address text NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id bigserial PRIMARY KEY, action text NOT NULL, actor text, target text, outcome text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_created_idx ON audit_events(created_at);
CREATE TABLE outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic text NOT NULL, idempotency_key text NOT NULL UNIQUE, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK(attempts >= 0), available_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, dead_lettered_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending_idx ON outbox(processed_at,available_at);
CREATE TABLE keeper_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chain_id bigint NOT NULL, vault_address text NOT NULL, job_type text NOT NULL, idempotency_key text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('PENDING','RUNNING','RETRY','DEAD','DONE')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts >= 0), available_at timestamptz NOT NULL DEFAULT now(), lease_owner text, lease_until timestamptz, payload jsonb NOT NULL DEFAULT '{}', last_error text, updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX keeper_jobs_ready_idx ON keeper_jobs(status,available_at);
